INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Dezimalsystem immer auf die Basis 10 beschränkt?', 2, '[{"text": "Ja", "correct": true, "because": "Definition des Dezimalsystems"}, {"text": "Nein", "correct": false, "because": "Andere Basen sind andere Systeme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Basis nutzt das Dezimalsystem?', 3, '[{"text": "10", "correct": true, "because": "Grundlage des Systems"}, {"text": "2", "correct": false, "because": "Das ist binär"}, {"text": "16", "correct": false, "because": "Das ist hexadezimal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat das Dezimalsystem?', 5, '[{"text": "Zehn Ziffern", "correct": true, "because": "0 bis 9"}, {"text": "Stellenwertsystem", "correct": true, "because": "Position bestimmt Wert"}, {"text": "Nur Binärcodes", "correct": false, "because": "Nicht binär"}, {"text": "Unendliche Basen", "correct": false, "because": "Fest auf 10"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Dezimalsystem ist ein Zahlensystem. b) Es nutzt nur Bits.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bits sind binär"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich im Dezimalsystem rechne?', 4, '[{"text": "Stellenwerte", "correct": false, "because": "Kern des Systems"}, {"text": "Ziffern 0-9", "correct": false, "because": "Grundelemente"}, {"text": "Hexadezimalwerte", "correct": true, "because": "Anderes System"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Dezimalsystem auch Buchstaben nutzt?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Ziffern 0-9"}, {"text": "Ja", "correct": false, "because": "Buchstaben sind hexadezimal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Zahlensystem wird im Alltag meist verwendet?', 3, '[{"text": "Dezimal", "correct": true, "because": "Standard für Menschen"}, {"text": "Binär", "correct": false, "because": "Computer-intern"}, {"text": "Oktal", "correct": false, "because": "Seltener genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale definieren das Dezimalsystem?', 5, '[{"text": "Basis 10", "correct": true, "because": "Grundprinzip"}, {"text": "Positionssystem", "correct": true, "because": "Wert nach Position"}, {"text": "Binäre Ziffern", "correct": false, "because": "Nicht binär"}, {"text": "Variable Basis", "correct": false, "because": "Fest auf 10"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Das Dezimalsystem ist universell. b) Es ist für Computer ideal. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Computer bevorzugen Binär"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um im Dezimalsystem zu arbeiten?', 4, '[{"text": "Ziffern", "correct": false, "because": "Grundbausteine"}, {"text": "Stellenwerte", "correct": false, "because": "Bestimmen Wert"}, {"text": "Binärcodierung", "correct": true, "because": "Anderes System"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat das Dezimalsystem 16 Ziffern?', 2, '[{"text": "Nein", "correct": true, "because": "Nur 10 Ziffern"}, {"text": "Ja", "correct": false, "because": "16 ist hexadezimal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Systeme unterscheiden sich vom Dezimalsystem?', 4, '[{"text": "Binärsystem", "correct": true, "because": "Basis 2"}, {"text": "Hexadezimalsystem", "correct": true, "because": "Basis 16"}, {"text": "Dezimalsystem selbst", "correct": false, "because": "Ist das Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Dezimalsystem für Speichergrößen genutzt wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "IT nutzt oft 1024"}, {"text": "Ja", "correct": false, "because": "Verwechslung mit SI"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Verständnis des Dezimalsystems?', 3, '[{"text": "Stellenwertprinzip", "correct": true, "because": "Kern des Systems"}, {"text": "Binärumrechnung", "correct": false, "because": "Anderes System"}, {"text": "Schnelle Addition", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Dezimalsystem nutzt 0-9. b) Es ist das einzige Zahlensystem.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Es gibt weitere Systeme"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Dezimalsystem?', 5, '[{"text": "Einfache Lesbarkeit", "correct": true, "because": "Intuitiv für Menschen"}, {"text": "Universelle Nutzung", "correct": true, "because": "Weltweiter Standard"}, {"text": "Hohe Effizienz für CPUs", "correct": false, "because": "Binär ist effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist im Dezimalsystem unwichtig?', 3, '[{"text": "Ziffernfolge", "correct": false, "because": "Bestimmt Wert"}, {"text": "Basis 10", "correct": false, "because": "Grundprinzip"}, {"text": "Oktalzahlen", "correct": true, "because": "Anderes System"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Wird das Dezimalsystem in der IT bevorzugt?', 3, '[{"text": "Nein", "correct": true, "because": "Binär und Hex dominieren"}, {"text": "Ja", "correct": false, "because": "Nur für Anzeige genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Dezimalsystem auch für Binärcodes gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Binär ist Basis 2"}, {"text": "Ja", "correct": false, "because": "Verwechslung mit Umrechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip ist für das Dezimalsystem zentral?', 4, '[{"text": "Stellenwert", "correct": true, "because": "Position definiert Wert"}, {"text": "Bitfolgen", "correct": false, "because": "Binärsystem"}, {"text": "Hexadezimalzahlen", "correct": false, "because": "Anderes System"}]');
